def to_minutes(apps, schema_editor):
    """
    The two time rules were whole hours and are now minutes from midnight.

    Without this, a saved "do not enter before 10:00" would start reading as 00:10 - a rule
    that can never be broken, reported as kept forever. **A silent change of units is the
    worst kind of migration to skip**, because nothing fails and the answer just quietly
    becomes wrong.
    """
    rules = apps.get_model("mentor", "TraderRule")

    for row in rules.objects.filter(kind__in = ("no_before", "no_after")):
        if row.number is not None and row.number <= 23:
            row.number = row.number * 60
            row.save(update_fields = ["number"])


def setups_become_a_rule_in_his_words(apps, schema_editor):
    """
    `only_setups` is gone because the free-text rule already is it, and better - so the rows
    are converted rather than deleted. "Trade only these setups" is exactly one condition
    satisfied by any of several tags, which is the shape the free-text rule stores natively.

    The sentence is written for him in the same words the old rule read in, so he recognises
    it; the terms come straight from the list he had already chosen, so nothing is guessed.
    """
    rules = apps.get_model("mentor", "TraderRule")

    for row in rules.objects.filter(kind = "only_setups"):
        allowed = [part.strip().lower() for part in (row.setups or "").replace(";", ",").split(",")]
        allowed = [part for part in allowed if part]

        if not allowed:
            row.delete()
            continue

        row.kind = "custom"
        row.text = f"לסחור רק בסטאפים: {', '.join(allowed)}"
        row.terms = {"require": [allowed[:4]], "forbid": []}
        row.known_labels = []
        row.number = None
        row.save()


